package repo

import (
	"errors"
	"io"
	"regexp"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"
)

// The committed Gateway API definitions are the ones the pinned versions
// render, and are the Gateway API's and nothing else.
//
// They are generated by `task render-gateway-api` and committed, because the
// chart they come from cannot be installed as a release: Helm keeps a
// release in one Secret, and this one is larger than a Secret may be. A
// generated file nobody can prove is current becomes the truth while
// claiming to be a copy, so it is held to its two pins. The chart's version
// is in the header, which anybody can edit. The Gateway API's own is on
// every definition, as the annotation the project puts there, and cannot
// be changed without changing what is applied.
//
// And nothing else of the chart's. The chart carries its publisher's own
// kinds too, and the front door is told what to route by the Gateway API
// alone (docs/epochs/04-observability.md): a definition of another group
// here is a second way of telling it.
func TestTheRenderedGatewayAPIDefinitionsMatchTheirPins(t *testing.T) {
	const group = "gateway.networking.k8s.io"
	path, body := fluxObject(t, "CustomResourceDefinition", "gateways."+group)

	env := readRepoFile(t, "scripts/versions.env")
	pinned := func(name string) string {
		m := regexp.MustCompile(`(?m)^` + name + `=(.+)$`).FindStringSubmatch(env)
		if m == nil {
			t.Fatalf("scripts/versions.env declares no %s.\n\nEvery version this estate takes is pinned in that one file.", name)
		}
		return strings.TrimSpace(m[1])
	}
	chart, api := pinned("TRAEFIK_CRDS_VERSION"), pinned("GATEWAY_API_VERSION")

	if !strings.Contains(body, "traefik-crds "+chart+" ") {
		t.Errorf("%s: its header does not name chart version %s.\n\nRe-render it with `task render-gateway-api`.", path, chart)
	}

	found := map[string]bool{}
	dec := yaml.NewDecoder(strings.NewReader(body))
	for {
		var doc struct {
			Kind     string `yaml:"kind"`
			Metadata struct {
				Name        string            `yaml:"name"`
				Annotations map[string]string `yaml:"annotations"`
			} `yaml:"metadata"`
			Spec struct {
				Group string `yaml:"group"`
			} `yaml:"spec"`
		}
		err := dec.Decode(&doc)
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			t.Fatalf("%s is not YAML that can be read: %v", path, err)
		}
		if doc.Kind == "" {
			continue
		}
		switch {
		case doc.Kind != "CustomResourceDefinition" || doc.Spec.Group != group:
			t.Errorf("%s holds the %s %s, which is not a definition of the Gateway API's.\n\n"+
				"The front door is told what to route by the Gateway API alone. Render with only that asked of the chart.", path, doc.Kind, doc.Metadata.Name)
		case doc.Metadata.Annotations[group+"/bundle-version"] != "v"+api:
			t.Errorf("%s: the definition %s says it is of Gateway API %s, and scripts/versions.env pins %s.\n\n"+
				"The file was rendered from a chart carrying another version than the one this repository claims. Re-render it with `task render-gateway-api`, or correct the pin.",
				path, doc.Metadata.Name, doc.Metadata.Annotations[group+"/bundle-version"], api)
		default:
			found[doc.Metadata.Name] = true
		}
	}
	// What the manifests here are written in. A render that left one out
	// would be applied cleanly and every object of that kind refused.
	for _, kind := range []string{"gatewayclasses", "gateways", "httproutes"} {
		if !found[kind+"."+group] {
			t.Errorf("%s does not define %s, which this site's own manifests are written in.", path, kind)
		}
	}
}
